function bytes(encoded) {
  return Uint8Array.from(atob(encoded), value => value.charCodeAt(0));
}

function float32Values(encoded, count) {
  const data = bytes(encoded);
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  return Array.from({ length: count * 3 }, (_, index) => (
    view.getFloat32(index * 4, true)
  ));
}

function uint16Values(encoded, count) {
  const data = bytes(encoded);
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  return Array.from({ length: count * 3 }, (_, index) => (
    view.getUint16(index * 2, true)
  ));
}

function unpack(record) {
  return { ...record, volumes: record.volumes.map(volume => {
    const { vertexData, vertexCount, ...metadata } = volume;
    return { ...metadata, vertices: float32Values(vertexData, vertexCount),
      plates: volume.plates.map(plate => {
        const { triangleData, triangleCount, ...plateMetadata } = plate;
        return { ...plateMetadata, triangles: uint16Values(triangleData, triangleCount) };
      })
    };
  }) };
}

export const GENERATED_VEHICLE_ARMOR_COLLISIONS = Object.freeze(
  Object.fromEntries(Object.entries(PACKED_RECORDS).map(([id, record]) => [id, unpack(record)]))
);

export function getGeneratedVehicleArmorCollision(modelId) {
  return GENERATED_VEHICLE_ARMOR_COLLISIONS[modelId] ?? null;
}
